import { runs, streams } from "@trigger.dev/sdk/v3";

async function main() {
  const run = await runs.trigger({
    task: "agentTask-ai_agent_with_tool_and_streaming__4XzRy55",
    payload: {
      city: "Paris",
    },
  });

  const stream = await streams.read(run.id, "ai-output");

  for await (const chunk of stream) {
    process.stdout.write(chunk);
  }

  console.log(`\nRun ID: ${run.id}`);
}

main().catch(console.error);

